-- GENERATED by tools/gen_state_mod.py from templates/state_names and data/states/us_minnesota; edit those, not this file.
-- Pure logic (content/square_names_us_minnesota/sn_logic.lua): normalization, climate keys, town sampling, street and
-- station picking, params. Synthetic data, so the same tests run for every state mod.

local MOD = "square_names_us_minnesota"
local L = ug_require(MOD .. "::/" .. MOD .. "/sn_logic.lua")

-- Deterministic float rng in [0, 1).
local function lcg(seed)
	local s = seed
	return function()
		s = (s * 1103515245 + 12345) % 2147483648
		return s / 2147483648
	end
end

local function towns()
	local t = {}
	local function add(n, tags, p) t[#t + 1] = { n = n, t = tags, p = p } end
	add("Big West A", { "west", "big" }, 700000)
	add("Big West B", { "west", "big" }, 200000)
	add("Big East A", { "east", "big" }, 220000)
	add("Big West C", { "west", "big" }, 150000)
	add("Big West D", { "west", "big" }, 120000)
	add("Big East B", { "east", "big" }, 90000)
	for i = 1, 40 do add("West " .. i, { "west" }, 5000 + i) end
	for i = 1, 30 do add("East " .. i, { "east" }, 4000 + i) end
	for i = 1, 10 do add("Coast " .. i, { "west", "coast" }, 2000 + i) end
	for i = 1, 8 do add("Mtn " .. i, { "east", "mountain" }, 500 + i) end
	table.sort(t, function(a, b) return a.p > b.p end)
	return t
end

local function byName(list)
	local s = {}
	for _, n in ipairs(list) do s[n] = (s[n] or 0) + 1 end
	return s
end

local function tagsOf(ts)
	local m = {}
	for _, t in ipairs(ts) do m[t.n] = t.t end
	return m
end

local function has(tags, tag)
	for _, t in ipairs(tags) do if t == tag then return true end end
	return false
end

test("normalize: case, spaces, accents, apostrophes", function()
	eq(L.normalize("  Pike   Street "), "pike street")
	eq(L.normalize("PIKE street"), "pike street")
	eq(L.normalize("Café Ñandú"), "cafe nandu")
	eq(L.normalize("Browne's Addition"), "brownes addition")
	eq(L.normalize("Browne\226\128\153s Addition"), "brownes addition")
	eq(L.normalize("Sea-Tac Airport"), "sea tac airport")
	eq(L.normalize(nil), "")
end)

test("normalize: Latin Extended-A, okina and left quote fold like the typed ASCII form", function()
	eq(L.normalize("Utqiaġvik"), "utqiagvik")
	eq(L.normalize("Cañon City"), L.normalize("Canon City"))
	eq(L.normalize("Doña Ana"), "dona ana")
	eq(L.normalize("Hāna"), "hana")
	eq(L.normalize("Kōloa"), "koloa")
	eq(L.normalize("ŁÓDŹ Œuvre"), "lodz oeuvre")
	eq(L.normalize("Straße"), "strasse")
	eq(L.normalize("Hawaiʻi Kai"), "hawaii kai", "okina U+02BB dropped")
	eq(L.normalize("Hawai\226\128\152i Kai"), "hawaii kai", "left single quote U+2018 dropped")
	eq(L.normalize("ʻEwa Beach"), "ewa beach")
	eq(L.baseName("Kailua-Kona Ālii Drive East"), "kailua kona alii drive")
	-- unknown multi-byte letters stay as separators, never break the string
	eq(L.normalize("Tōkyō 東京"), "tokyo")
end)

