test("climateKey takes the last path segment", function()
	eq(L.climateKey("::/climates/dry/dry.clima"), "dry")
	eq(L.climateKey("::/climates/temperate/temperate.clima"), "temperate")
	eq(L.climateKey("somemod::/climates/alpine/alpine.clima"), "alpine")
	eq(L.climateKey("tropical"), "tropical")
	eq(L.climateKey(""), nil)
	eq(L.climateKey(nil), nil)
	local sd = { climates = { dry = { east = 85 } } }
	eq(L.climateWeights(sd, "::/climates/dry/dry.clima"), { east = 85 })
	eq(L.climateWeights(sd, "::/climates/alpine/alpine.clima"), nil, "unknown climate: whole state")
	eq(L.climateWeights(sd, nil), nil)
end)

test("sampleTowns: exact count, no duplicates, top-weighted big towns first", function()
	local ts = towns()
	local res = L.sampleTowns(ts, 13, { west = 70, coast = 15, east = 15 }, lcg(1))
	eq(#res, 13)
	for n, c in pairs(byName(res)) do eq(c, 1, "duplicate " .. n) end
	eq(res[1], "Big West A")
	eq(res[2], "Big West B")
	eq(res[3], "Big West C")
	eq(res[4], "Big West D", "every big town of the top-weighted tag fits in half the slots")
end)

test("sampleTowns: climate pools are respected", function()
	local ts = towns()
	local tags = tagsOf(ts)
	for seed = 1, 20 do
		local res = L.sampleTowns(ts, 20, { east = 85, mountain = 15 }, lcg(seed))
		eq(#res, 20)
		for _, n in ipairs(res) do
			ok(has(tags[n], "east") or has(tags[n], "mountain"), "dry pick outside the pool: " .. n)
		end
		eq(res[1], "Big East A")
	end
end)

test("sampleTowns: weight-0 tags only top up, then the whole state, then repeats", function()
	local ts = towns()
	local tags = tagsOf(ts)
	local res = L.sampleTowns(ts, 15, { coast = 50, west = 0 }, lcg(3))
	eq(#res, 15)
	local coast = 0
	for i, n in ipairs(res) do
		if has(tags[n], "coast") then coast = coast + 1 end
		if i <= 10 then ok(has(tags[n], "coast"), "coast first: " .. n) end
	end
	eq(coast, 10)
	for i = 11, 15 do ok(has(tags[res[i]], "west"), "top-up from west: " .. res[i]) end
	-- more than the coast + west pools: whole state next
	local res2 = L.sampleTowns(ts, 70, { coast = 50, west = 0 }, lcg(4))
	eq(#res2, 70)
	for n, c in pairs(byName(res2)) do eq(c, 1, "duplicate " .. n) end
	-- more than all towns: repeats, still the exact count
	local res3 = L.sampleTowns(ts, #ts + 5, { west = 1 }, lcg(5))
	eq(#res3, #ts + 5)
	eq(#L.sampleTowns(ts, 0, nil, lcg(1)), 0)
end)

test("sampleTowns: no climate = whole state, all big towns can be guaranteed", function()
	local ts = towns()
	local res = L.sampleTowns(ts, 12, nil, lcg(7))
	eq(#res, 12)
	local s = byName(res)
	for _, n in ipairs({ "Big West A", "Big East A", "Big West B" }) do ok(s[n], "top 3 present: " .. n) end
	local big = 0
	for _, n in ipairs(res) do if n:find("^Big") then big = big + 1 end end
	ok(big >= 6, "half of the slots go to big towns, got " .. big)
	eq(#L.sampleTowns(ts, -1, nil), #ts, "num = -1 returns every name")
	eq(L.poolSize(ts, nil), #ts)
	eq(L.poolSize(ts, { mountain = 1 }), 8)
end)

test("sampleTowns: bigger towns are picked more often", function()
	local ts = {
		{ n = "Large", t = { "x" }, p = 200000 },
		{ n = "Small", t = { "x" }, p = 100 },
	}
	local large = 0
	for seed = 1, 200 do
		if L.sampleTowns(ts, 1, { x = 1, y = 1 }, lcg(seed))[1] == "Large" then large = large + 1 end
	end
	ok(large > 150, "large picked " .. large .. "/200")
end)

