test("pickStreet: first unused, names in use compared without suffixes", function()
	local streets = { "Pike Street", "Pine Street", "Union Street" }
	eq(L.pickStreet(streets, L.newUsed({})), "Pike Street")
	eq(L.pickStreet(streets, L.newUsed({ "PIKE STREET" })), "Pine Street")
	eq(L.pickStreet(streets, L.newUsed({ "Pike Street East", "Pine Street Station" })), "Union Street")
	eq(L.pickStreet({}, L.newUsed({})), nil)
end)

test("pickStreet: exhausted list gets the engine's suffix style, unique", function()
	local streets = { "Pike Street", "Pine Street" }
	local used = L.newUsed({ "Pike Street", "Pine Street" })
	local seen = {}
	for _ = 1, 12 do
		local n = L.pickStreet(streets, used)
		ok(n ~= nil)
		ok(not seen[n], "repeat " .. tostring(n))
		seen[n] = true
		L.addUsed(used, n)
	end
	ok(seen["Pike Street East"] and seen["Pine Street East"] and seen["Pike Street West"], "East/West first")
	ok(seen["Pike Street #2"], "then #2")
end)

test("pickStation by kind; exhausted list leaves the default", function()
	local city = { rail = { "King Street", "Westlake" }, airport = { "Sea-Tac Airport" }, harbor = { "Colman Dock" },
		neighborhoods = { "Ballard" } }
	eq(L.pickStation(L.stationList(city, "rail"), L.newUsed({})), "King Street")
	eq(L.pickStation(L.stationList(city, "rail"), L.newUsed({ "King Street Station" })), "Westlake")
	eq(L.pickStation(L.stationList(city, "airport"), L.newUsed({})), "Sea-Tac Airport")
	eq(L.pickStation(L.stationList(city, "harbor"), L.newUsed({})), "Colman Dock")
	eq(L.pickStation(L.stationList(city, "street"), L.newUsed({})), "Ballard")
	eq(L.pickStation(L.stationList(city, "airport"), L.newUsed({ "Sea-Tac Airport" })), nil)
	eq(L.stationList(city, "stop"), nil)
	eq(L.pickStation(nil, L.newUsed({})), nil)
end)

