test("findCity by key and alias, normalized", function()
	local cities = { ["Seattle"] = { streets = { "Pike Street" } }, ["SeaTac"] = { aliases = { "Sea-Tac" } } }
	ok(L.findCity(cities, "seattle") == cities["Seattle"])
	ok(L.findCity(cities, " SEATTLE ") == cities["Seattle"])
