	eq(#s, 4)
	local set = byName(s)
	for _, k in ipairs({ "a", "b", "c", "d" }) do eq(set[k], 1) end
end)

test("cityAllowed: contested city names (G9)", function()
	local c = { portland = "square_names_us_oregon", salem = "square_names_us_zz" }
	local me = "square_names_us_zz"
	local base = "::/names/usa/usa.names"
	local active = { square_names_us_oregon = {}, [me] = {} }
	ok(not L.cityAllowed(c, "Portland", me, active, base), "lost and the winner is active")
	ok(L.cityAllowed(c, "Portland", me, { [me] = {} }, base), "winner not active")
	ok(L.cityAllowed(c, "Portland", me, active, me .. "::/names/" .. me .. "/x.names"), "own name set")
	ok(L.cityAllowed(c, "Salem", me, active, base), "this mod won")
	ok(L.cityAllowed(c, "Seattle", me, active, base), "not contested")
	ok(not L.cityAllowed(c, "  PORTLAND ", me, active, nil), "normalized lookup; no name set known")
	ok(L.cityAllowed(nil, "Portland", me, active, base), "no data")
	ok(L.cityAllowed(c, nil, me, active, base))
end)

